const puzzleTypes = [
  "word_unlock",
  "odd_one_out",
  "sequence_puzzle",
  "mini_riddle"
];

// Difficulty rotation:
// Day 1: medium
// Day 2: easy
// Day 3: hard
// Day 4: medium
// Day 5: easy
// Day 6: hard
const difficultyTypes = [
  "medium",
  "easy",
  "hard"
];

// Use today's date to rotate puzzle type and difficulty
const today = new Date();

// Create a simple day number
const startDate = new Date("2026-05-14");
const diffTime = today.getTime() - startDate.getTime();
const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));

// Rotate between 4 puzzle types
const selectedPuzzleIndex =
  ((diffDays % puzzleTypes.length) + puzzleTypes.length) % puzzleTypes.length;

const selectedPuzzleType = puzzleTypes[selectedPuzzleIndex];

// Rotate between 3 difficulty levels
const selectedDifficultyIndex =
  ((diffDays % difficultyTypes.length) + difficultyTypes.length) % difficultyTypes.length;

const selectedDifficulty = difficultyTypes[selectedDifficultyIndex];

return [
  {
    json: {
      date: today.toISOString().split("T")[0],
      puzzle_type: selectedPuzzleType,
      difficulty: selectedDifficulty,
      rotation_day_number: diffDays + 1
    }
  }
];

const raw = $json.output || $json.text || $json.content || "";

if (!raw) {
  throw new Error("No AI output found. Expected output field from AI Agent.");
}

const cleaned = raw
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

let puzzle;

try {
  puzzle = JSON.parse(cleaned);
} catch (error) {
  throw new Error(
    "AI did not return valid JSON: " + error.message + "\n\nRaw output:\n" + raw
  );
}

return [
  {
    json: puzzle
  }
];

const puzzle = $json;

const errors = [];

function normalizeText(value) {
  return String(value || "").trim().toUpperCase();
}

function normalizeString(value) {
  return String(value || "").trim();
}

function hasValue(value) {
  return value !== undefined && value !== null && String(value).trim() !== "";
}

if (!puzzle.puzzle_type) {
  errors.push("Missing puzzle_type.");
}

if (!puzzle.answer) {
  errors.push("Missing top-level answer.");
}

if (!puzzle.puzzle_data || typeof puzzle.puzzle_data !== "object") {
  errors.push("Missing puzzle_data object.");
}

if (!["word_unlock", "odd_one_out", "sequence_puzzle", "mini_riddle"].includes(puzzle.puzzle_type)) {
  errors.push(`Unsupported puzzle_type: ${puzzle.puzzle_type}`);
}

/* -----------------------------
   WORD UNLOCK VALIDATION
------------------------------ */

if (puzzle.puzzle_type === "word_unlock") {
  const clues = puzzle.puzzle_data?.clues;

  if (!Array.isArray(clues)) {
    errors.push("word_unlock puzzle_data.clues must be an array.");
  } else {
    if (clues.length !== 5) {
      errors.push(`word_unlock must have exactly 5 clues. Found ${clues.length}.`);
    }

    const revealedLetters = [];

    clues.forEach((clue, index) => {
      const clueNumber = Number(clue.clue_number || index + 1);
      const answer = normalizeText(clue.answer);
      const revealedLetter = normalizeText(clue.revealed_letter);
      const position = Number(clue.revealed_letter_position_in_answer);

      if (!hasValue(clue.clue)) {
        errors.push(`Clue ${clueNumber}: missing clue.`);
      }

      if (!hasValue(clue.hint)) {
        errors.push(`Clue ${clueNumber}: missing hint.`);
      }

      if (!answer) {
        errors.push(`Clue ${clueNumber}: missing answer.`);
        return;
      }

      if (!revealedLetter) {
        errors.push(`Clue ${clueNumber}: missing revealed_letter.`);
        return;
      }

      if (revealedLetter.length !== 1) {
        errors.push(`Clue ${clueNumber}: revealed_letter must be exactly one letter.`);
        return;
      }

      if (!Number.isInteger(position) || position < 1 || position > answer.length) {
        errors.push(`Clue ${clueNumber}: invalid revealed_letter_position_in_answer.`);
        return;
      }

      const actualLetter = answer[position - 1];

      if (actualLetter !== revealedLetter) {
        errors.push(
          `Clue ${clueNumber}: position ${position} in "${answer}" is "${actualLetter}", not "${revealedLetter}".`
        );
      }

      revealedLetters.push(revealedLetter);

      clue.clue_number = clueNumber;
      clue.answer = answer;
      clue.revealed_letter = revealedLetter;
      clue.revealed_letter_position_in_answer = position;
    });

    const unlockedWord = revealedLetters.join("");
    const finalAnswer = normalizeText(puzzle.answer);

    puzzle.answer = finalAnswer;

    if (finalAnswer.length !== 5) {
      errors.push(`word_unlock answer must be 5 letters. Found ${finalAnswer.length}.`);
    }

    if (unlockedWord !== finalAnswer) {
      errors.push(
        `Revealed letters spell "${unlockedWord}", but top-level answer is "${finalAnswer}".`
      );
    }

    if (puzzle.puzzle_data.final_word_length !== finalAnswer.length) {
      errors.push(
        `final_word_length is ${puzzle.puzzle_data.final_word_length}, but answer length is ${finalAnswer.length}.`
      );
    }
  }
}

/* -----------------------------
   ODD ONE OUT VALIDATION
------------------------------ */

if (puzzle.puzzle_type === "odd_one_out") {
  const items = puzzle.puzzle_data?.items;
  const oddItemId = normalizeString(puzzle.puzzle_data?.odd_item_id).toUpperCase();
  const hiddenRule = normalizeString(puzzle.puzzle_data?.hidden_rule);
  const hint = normalizeString(puzzle.puzzle_data?.hint);

  if (!Array.isArray(items)) {
    errors.push("odd_one_out puzzle_data.items must be an array.");
  } else {
    if (items.length !== 5) {
      errors.push(`odd_one_out must have exactly 5 items. Found ${items.length}.`);
    }

    const itemIds = [];

    items.forEach((item, index) => {
      const expectedId = String.fromCharCode(65 + index);
      const id = normalizeString(item.id || expectedId).toUpperCase();
      const text = normalizeString(item.text);

      if (!id) {
        errors.push(`Item ${index + 1}: missing id.`);
      }

      if (!text) {
        errors.push(`Item ${id || index + 1}: missing text.`);
      }

      item.id = id;
      item.text = text;

      itemIds.push(id);
    });

    const uniqueIds = new Set(itemIds);

    if (uniqueIds.size !== itemIds.length) {
      errors.push("odd_one_out item ids must be unique.");
    }

    if (!oddItemId) {
      errors.push("odd_one_out missing odd_item_id.");
    } else if (!itemIds.includes(oddItemId)) {
      errors.push(`odd_item_id "${oddItemId}" does not match any item id.`);
    }

    if (!hiddenRule) {
      errors.push("odd_one_out missing hidden_rule.");
    }

    if (!hint) {
      errors.push("odd_one_out missing hint.");
    }

    const oddItem = items.find(item => item.id === oddItemId);

    if (oddItem && puzzle.answer) {
      const normalizedTopAnswer = normalizeString(puzzle.answer).toUpperCase();
      const normalizedOddText = normalizeString(oddItem.text).toUpperCase();

      if (normalizedTopAnswer !== normalizedOddText) {
        errors.push(
          `Top-level answer "${puzzle.answer}" does not match odd item text "${oddItem.text}".`
        );
      }
    }

    puzzle.puzzle_data.odd_item_id = oddItemId;
    puzzle.puzzle_data.hidden_rule = hiddenRule;
    puzzle.puzzle_data.hint = hint;

    if (oddItem) {
      puzzle.answer = oddItem.text;
    }
  }
}

/* -----------------------------
   SEQUENCE / QUICK LOGIC VALIDATION
------------------------------ */

if (puzzle.puzzle_type === "sequence_puzzle") {
  const sequence = puzzle.puzzle_data?.sequence;
  const options = puzzle.puzzle_data?.options;
  const correctOptionId = normalizeString(puzzle.puzzle_data?.correct_option_id).toUpperCase();
  const patternType = normalizeString(puzzle.puzzle_data?.pattern_type);
  const hint = normalizeString(puzzle.puzzle_data?.hint);

  const normalizedPatternType = patternType.toLowerCase();

  const singlePromptPatternTypes = [
    "order-of-operations",
    "bodmas",
    "bidmas",
    "arithmetic",
    "quick-arithmetic",
    "quick-logic",
    "missing-number",
    "missing-operator",
    "logic-puzzle",
    "math-logic",
    "calculation"
  ];

  const allowsSinglePrompt = singlePromptPatternTypes.includes(normalizedPatternType);

  if (!Array.isArray(sequence)) {
    errors.push("sequence_puzzle puzzle_data.sequence must be an array.");
  } else {
    if (sequence.length < 1) {
      errors.push("sequence_puzzle sequence must contain at least 1 item.");
    }

    if (!allowsSinglePrompt && sequence.length < 3) {
      errors.push(
        `sequence_puzzle sequence should have at least 3 items for pattern_type "${patternType}". Found ${sequence.length}.`
      );
    }

    if (allowsSinglePrompt && sequence.length !== 1) {
      errors.push(
        `sequence_puzzle with pattern_type "${patternType}" should usually contain exactly 1 puzzle expression/prompt in sequence. Found ${sequence.length}.`
      );
    }
  }

  if (!Array.isArray(options)) {
    errors.push("sequence_puzzle puzzle_data.options must be an array.");
  } else {
    if (options.length !== 4) {
      errors.push(`sequence_puzzle must have exactly 4 options. Found ${options.length}.`);
    }

    const optionIds = [];

    options.forEach((option, index) => {
      const expectedId = String.fromCharCode(65 + index);
      const id = normalizeString(option.id || expectedId).toUpperCase();
      const text = normalizeString(option.text);

      if (!id) {
        errors.push(`Option ${index + 1}: missing id.`);
      }

      if (!text) {
        errors.push(`Option ${id || index + 1}: missing text.`);
      }

      option.id = id;
      option.text = text;

      optionIds.push(id);
    });

    const uniqueOptionIds = new Set(optionIds);

    if (uniqueOptionIds.size !== optionIds.length) {
      errors.push("sequence_puzzle option ids must be unique.");
    }

    if (!correctOptionId) {
      errors.push("sequence_puzzle missing correct_option_id.");
    } else if (!optionIds.includes(correctOptionId)) {
      errors.push(`correct_option_id "${correctOptionId}" does not match any option id.`);
    }

    const correctOption = options.find(option => option.id === correctOptionId);

    if (correctOption && puzzle.answer) {
      const normalizedTopAnswer = normalizeString(puzzle.answer).toUpperCase();
      const normalizedCorrectText = normalizeString(correctOption.text).toUpperCase();

      if (normalizedTopAnswer !== normalizedCorrectText) {
        errors.push(
          `Top-level answer "${puzzle.answer}" does not match correct option text "${correctOption.text}".`
        );
      }
    }

    if (correctOption) {
      puzzle.answer = correctOption.text;
    }
  }

  if (!hasValue(puzzle.puzzle_data?.question)) {
    errors.push("sequence_puzzle missing question.");
  }

  if (!patternType) {
    errors.push("sequence_puzzle missing pattern_type.");
  }

  if (!hint) {
    errors.push("sequence_puzzle missing hint.");
  }

  puzzle.puzzle_data.correct_option_id = correctOptionId;
  puzzle.puzzle_data.pattern_type = patternType;
  puzzle.puzzle_data.hint = hint;
}

/* -----------------------------
   MINI RIDDLE VALIDATION
------------------------------ */

if (puzzle.puzzle_type === "mini_riddle") {
  const riddle = normalizeString(puzzle.puzzle_data?.riddle);
  const hint = normalizeString(puzzle.puzzle_data?.hint);
  const dataAnswer = normalizeText(puzzle.puzzle_data?.answer);
  const topAnswer = normalizeText(puzzle.answer);

  if (!riddle) {
    errors.push("mini_riddle missing riddle.");
  }

  if (!hint) {
    errors.push("mini_riddle missing hint.");
  }

  if (!dataAnswer) {
    errors.push("mini_riddle missing puzzle_data.answer.");
  }

  if (!topAnswer) {
    errors.push("mini_riddle missing top-level answer.");
  }

  if (dataAnswer && topAnswer && dataAnswer !== topAnswer) {
    errors.push(
      `mini_riddle top-level answer "${puzzle.answer}" does not match puzzle_data.answer "${puzzle.puzzle_data.answer}".`
    );
  }

  if (dataAnswer && dataAnswer.length < 2) {
    errors.push("mini_riddle answer is too short.");
  }

  if (dataAnswer && dataAnswer.length > 30) {
    errors.push("mini_riddle answer is too long.");
  }

  puzzle.puzzle_data.riddle = riddle;
  puzzle.puzzle_data.hint = hint;
  puzzle.puzzle_data.answer = dataAnswer;
  puzzle.answer = dataAnswer || topAnswer;
}

/* -----------------------------
   COMMON FIELD CHECKS
------------------------------ */

if (!hasValue(puzzle.title)) {
  errors.push("Missing title.");
}

if (!["easy", "medium", "hard"].includes(String(puzzle.difficulty || "").toLowerCase())) {
  errors.push(`Invalid difficulty: ${puzzle.difficulty}`);
}

if (
  !Number.isInteger(Number(puzzle.estimated_time_minutes)) ||
  Number(puzzle.estimated_time_minutes) < 3 ||
  Number(puzzle.estimated_time_minutes) > 7
) {
  errors.push("estimated_time_minutes must be a number between 3 and 7.");
}

if (!hasValue(puzzle.instructions)) {
  errors.push("Missing instructions.");
}

if (!hasValue(puzzle.explanation)) {
  errors.push("Missing explanation.");
}

if (!hasValue(puzzle.share_text)) {
  errors.push("Missing share_text.");
}

if (!puzzle.gameplay_rules || typeof puzzle.gameplay_rules !== "object") {
  errors.push("Missing gameplay_rules object.");
}

/* -----------------------------
   GAMEPLAY RULES VALIDATION
------------------------------ */

if (puzzle.gameplay_rules && typeof puzzle.gameplay_rules === "object") {
  const rules = puzzle.gameplay_rules;

  if (puzzle.puzzle_type === "word_unlock") {
    if (!Number.isInteger(Number(rules.clue_attempts_allowed))) {
      errors.push("word_unlock gameplay_rules missing clue_attempts_allowed.");
    }

    if (!Number.isInteger(Number(rules.show_hint_after_wrong_attempts))) {
      errors.push("word_unlock gameplay_rules missing show_hint_after_wrong_attempts.");
    }

    if (!Number.isInteger(Number(rules.reveal_answer_after_wrong_attempts))) {
      errors.push("word_unlock gameplay_rules missing reveal_answer_after_wrong_attempts.");
    }

    if (!Number.isInteger(Number(rules.final_answer_attempts_allowed))) {
      errors.push("word_unlock gameplay_rules missing final_answer_attempts_allowed.");
    }
  }

  if (
    puzzle.puzzle_type === "odd_one_out" ||
    puzzle.puzzle_type === "sequence_puzzle" ||
    puzzle.puzzle_type === "mini_riddle"
  ) {
    if (!Number.isInteger(Number(rules.attempts_allowed))) {
      errors.push(`${puzzle.puzzle_type} gameplay_rules missing attempts_allowed.`);
    }

    if (!Number.isInteger(Number(rules.show_hint_after_wrong_attempts))) {
      errors.push(`${puzzle.puzzle_type} gameplay_rules missing show_hint_after_wrong_attempts.`);
    }

    if (!Number.isInteger(Number(rules.reveal_answer_after_wrong_attempts))) {
      errors.push(`${puzzle.puzzle_type} gameplay_rules missing reveal_answer_after_wrong_attempts.`);
    }

    if ("clue_attempts_allowed" in rules) {
      errors.push(`${puzzle.puzzle_type} should use attempts_allowed, not clue_attempts_allowed.`);
    }

    if ("final_answer_attempts_allowed" in rules) {
      errors.push(`${puzzle.puzzle_type} should not use final_answer_attempts_allowed.`);
    }
  }
}

puzzle.validation = {
  is_valid: errors.length === 0,
  errors
};

return [
  {
    json: puzzle
  }
];

const puzzle = $json;

const fixLog = [];
const errors = [];

function normalizeText(value) {
  return String(value || "").trim().toUpperCase();
}

function normalizeString(value) {
  return String(value || "").trim();
}

function hasValue(value) {
  return value !== undefined && value !== null && String(value).trim() !== "";
}

if (!puzzle.puzzle_type) {
  errors.push("Missing puzzle_type. Cannot auto-fix.");
}

if (!puzzle.puzzle_data || typeof puzzle.puzzle_data !== "object") {
  errors.push("Missing puzzle_data object. Cannot auto-fix.");
}

/* -----------------------------
   COMMON LIGHT CLEANUP
------------------------------ */

if (puzzle.title) {
  puzzle.title = normalizeString(puzzle.title);
}

if (puzzle.instructions) {
  puzzle.instructions = normalizeString(puzzle.instructions);
}

if (puzzle.explanation) {
  puzzle.explanation = normalizeString(puzzle.explanation);
}

if (puzzle.share_text) {
  puzzle.share_text = normalizeString(puzzle.share_text);
}

if (puzzle.difficulty) {
  puzzle.difficulty = normalizeString(puzzle.difficulty).toLowerCase();
}

if (puzzle.status) {
  puzzle.status = normalizeString(puzzle.status).toLowerCase();
}

/* -----------------------------
   WORD UNLOCK AUTO-FIX
------------------------------ */

if (puzzle.puzzle_type === "word_unlock") {
  const clues = puzzle.puzzle_data?.clues;

  if (!Array.isArray(clues)) {
    errors.push("Missing puzzle_data.clues array. Cannot auto-fix word_unlock.");
  } else {
    clues.forEach((clue, index) => {
      const clueNumber = Number(clue.clue_number || index + 1);

      const answer = normalizeText(clue.answer);
      const revealedLetter = normalizeText(clue.revealed_letter);

      clue.clue_number = clueNumber;
      clue.answer = answer;
      clue.revealed_letter = revealedLetter;

      if (clue.clue) {
        clue.clue = normalizeString(clue.clue);
      }

      if (clue.hint) {
        clue.hint = normalizeString(clue.hint);
      }

      if (!answer) {
        errors.push(`Clue ${clueNumber}: missing answer.`);
        return;
      }

      if (!revealedLetter) {
        errors.push(`Clue ${clueNumber}: missing revealed_letter.`);
        return;
      }

      if (revealedLetter.length !== 1) {
        errors.push(`Clue ${clueNumber}: revealed_letter must be exactly one character.`);
        return;
      }

      let currentPosition = Number(clue.revealed_letter_position_in_answer);

      const currentPositionIsWrong =
        !Number.isInteger(currentPosition) ||
        currentPosition < 1 ||
        currentPosition > answer.length ||
        answer[currentPosition - 1] !== revealedLetter;

      if (currentPositionIsWrong) {
        const correctIndex = answer.indexOf(revealedLetter);

        if (correctIndex !== -1) {
          const correctPosition = correctIndex + 1;

          fixLog.push(
            `Clue ${clueNumber}: changed revealed_letter_position_in_answer from ${clue.revealed_letter_position_in_answer} to ${correctPosition}.`
          );

          clue.revealed_letter_position_in_answer = correctPosition;
        } else {
          errors.push(
            `Clue ${clueNumber}: cannot fix because revealed letter "${revealedLetter}" is not found in answer "${answer}".`
          );
        }
      } else {
        clue.revealed_letter_position_in_answer = currentPosition;
      }
    });

    if (puzzle.answer) {
      puzzle.answer = normalizeText(puzzle.answer);
    }

    if (puzzle.answer && puzzle.puzzle_data) {
      const correctLength = puzzle.answer.length;

      if (puzzle.puzzle_data.final_word_length !== correctLength) {
        fixLog.push(
          `Changed final_word_length from ${puzzle.puzzle_data.final_word_length} to ${correctLength}.`
        );

        puzzle.puzzle_data.final_word_length = correctLength;
      }
    }
  }
}

/* -----------------------------
   ODD ONE OUT AUTO-FIX
------------------------------ */

if (puzzle.puzzle_type === "odd_one_out") {
  const items = puzzle.puzzle_data?.items;

  if (!Array.isArray(items)) {
    errors.push("Missing puzzle_data.items array. Cannot auto-fix odd_one_out.");
  } else {
    puzzle.puzzle_data.items = items.map((item, index) => {
      const expectedId = String.fromCharCode(65 + index);
      const oldId = item.id;

      const fixedItem = {
        ...item,
        id: normalizeString(item.id || expectedId).toUpperCase(),
        text: normalizeString(item.text)
      };

      if (!oldId) {
        fixLog.push(`Item ${index + 1}: added missing id "${fixedItem.id}".`);
      }

      return fixedItem;
    });

    if (puzzle.puzzle_data.odd_item_id) {
      puzzle.puzzle_data.odd_item_id = normalizeString(puzzle.puzzle_data.odd_item_id).toUpperCase();
    }

    if (puzzle.puzzle_data.hidden_rule) {
      puzzle.puzzle_data.hidden_rule = normalizeString(puzzle.puzzle_data.hidden_rule);
    }

    if (puzzle.puzzle_data.hint) {
      puzzle.puzzle_data.hint = normalizeString(puzzle.puzzle_data.hint);
    }

    const oddItemId = puzzle.puzzle_data.odd_item_id;
    const oddItem = puzzle.puzzle_data.items.find(item => item.id === oddItemId);

    if (oddItem) {
      const oldAnswer = puzzle.answer;
      puzzle.answer = oddItem.text;

      if (normalizeString(oldAnswer).toUpperCase() !== normalizeString(oddItem.text).toUpperCase()) {
        fixLog.push(
          `Changed top-level answer from "${oldAnswer}" to odd item text "${oddItem.text}".`
        );
      }
    } else {
      errors.push(`Cannot auto-fix answer because odd_item_id "${oddItemId}" does not match any item.`);
    }
  }
}

/* -----------------------------
   SEQUENCE PUZZLE AUTO-FIX
------------------------------ */

if (puzzle.puzzle_type === "sequence_puzzle") {
  const options = puzzle.puzzle_data?.options;

  if (!Array.isArray(options)) {
    errors.push("Missing puzzle_data.options array. Cannot auto-fix sequence_puzzle.");
  } else {
    puzzle.puzzle_data.options = options.map((option, index) => {
      const expectedId = String.fromCharCode(65 + index);
      const oldId = option.id;

      const fixedOption = {
        ...option,
        id: normalizeString(option.id || expectedId).toUpperCase(),
        text: normalizeString(option.text)
      };

      if (!oldId) {
        fixLog.push(`Option ${index + 1}: added missing id "${fixedOption.id}".`);
      }

      return fixedOption;
    });

    if (puzzle.puzzle_data.correct_option_id) {
      puzzle.puzzle_data.correct_option_id = normalizeString(
        puzzle.puzzle_data.correct_option_id
      ).toUpperCase();
    }

    if (puzzle.puzzle_data.question) {
      puzzle.puzzle_data.question = normalizeString(puzzle.puzzle_data.question);
    }

    if (puzzle.puzzle_data.pattern_type) {
      puzzle.puzzle_data.pattern_type = normalizeString(puzzle.puzzle_data.pattern_type);
    }

    if (puzzle.puzzle_data.hint) {
      puzzle.puzzle_data.hint = normalizeString(puzzle.puzzle_data.hint);
    }

    const correctOptionId = puzzle.puzzle_data.correct_option_id;
    const correctOption = puzzle.puzzle_data.options.find(option => option.id === correctOptionId);

    if (correctOption) {
      const oldAnswer = puzzle.answer;
      puzzle.answer = correctOption.text;

      if (
        normalizeString(oldAnswer).toUpperCase() !==
        normalizeString(correctOption.text).toUpperCase()
      ) {
        fixLog.push(
          `Changed top-level answer from "${oldAnswer}" to correct option text "${correctOption.text}".`
        );
      }
    } else {
      errors.push(
        `Cannot auto-fix answer because correct_option_id "${correctOptionId}" does not match any option.`
      );
    }
  }

  if (Array.isArray(puzzle.puzzle_data?.sequence)) {
    puzzle.puzzle_data.sequence = puzzle.puzzle_data.sequence.map(item => {
      if (typeof item === "string") {
        return normalizeString(item);
      }

      return item;
    });
  }
}

/* -----------------------------
   MINI RIDDLE AUTO-FIX
------------------------------ */

if (puzzle.puzzle_type === "mini_riddle") {
  if (!puzzle.puzzle_data || typeof puzzle.puzzle_data !== "object") {
    errors.push("Missing puzzle_data object. Cannot auto-fix mini_riddle.");
  } else {
    if (puzzle.puzzle_data.riddle) {
      puzzle.puzzle_data.riddle = normalizeString(puzzle.puzzle_data.riddle);
    }

    if (puzzle.puzzle_data.hint) {
      puzzle.puzzle_data.hint = normalizeString(puzzle.puzzle_data.hint);
    }

    if (puzzle.puzzle_data.answer) {
      puzzle.puzzle_data.answer = normalizeText(puzzle.puzzle_data.answer);
    }

    if (puzzle.answer) {
      puzzle.answer = normalizeText(puzzle.answer);
    }

    if (puzzle.puzzle_data.answer && puzzle.answer !== puzzle.puzzle_data.answer) {
      const oldAnswer = puzzle.answer;
      puzzle.answer = puzzle.puzzle_data.answer;

      fixLog.push(
        `Changed top-level answer from "${oldAnswer}" to puzzle_data.answer "${puzzle.puzzle_data.answer}".`
      );
    }

    if (!puzzle.puzzle_data.answer && puzzle.answer) {
      puzzle.puzzle_data.answer = puzzle.answer;

      fixLog.push(
        `Added missing puzzle_data.answer from top-level answer "${puzzle.answer}".`
      );
    }

    if (puzzle.puzzle_data.answer && !puzzle.answer) {
      puzzle.answer = puzzle.puzzle_data.answer;

      fixLog.push(
        `Added missing top-level answer from puzzle_data.answer "${puzzle.puzzle_data.answer}".`
      );
    }

    if (!puzzle.puzzle_data.riddle) {
      errors.push("mini_riddle missing riddle. Cannot auto-fix missing riddle text.");
    }

    if (!puzzle.puzzle_data.hint) {
      errors.push("mini_riddle missing hint. Cannot auto-fix missing hint.");
    }

    if (!puzzle.puzzle_data.answer && !puzzle.answer) {
      errors.push("mini_riddle missing answer. Cannot auto-fix missing answer.");
    }
  }
}

/* -----------------------------
   CLEAN OLD VALIDATION
------------------------------ */

delete puzzle.validation;

puzzle.auto_fix = {
  attempted: true,
  fixed: fixLog.length > 0,
  fix_log: fixLog,
  remaining_errors: errors
};

return [
  {
    json: puzzle
  }
];

const puzzle = $json;

const errors = [];

function normalizeText(value) {
  return String(value || "").trim().toUpperCase();
}

function normalizeString(value) {
  return String(value || "").trim();
}

function hasValue(value) {
  return value !== undefined && value !== null && String(value).trim() !== "";
}

if (!puzzle.puzzle_type) {
  errors.push("Missing puzzle_type.");
}

if (!puzzle.answer) {
  errors.push("Missing top-level answer.");
}

if (!puzzle.puzzle_data || typeof puzzle.puzzle_data !== "object") {
  errors.push("Missing puzzle_data object.");
}

if (!["word_unlock", "odd_one_out", "sequence_puzzle", "mini_riddle"].includes(puzzle.puzzle_type)) {
  errors.push(`Unsupported puzzle_type: ${puzzle.puzzle_type}`);
}

/* -----------------------------
   WORD UNLOCK VALIDATION
------------------------------ */

if (puzzle.puzzle_type === "word_unlock") {
  const clues = puzzle.puzzle_data?.clues;

  if (!Array.isArray(clues)) {
    errors.push("word_unlock puzzle_data.clues must be an array.");
  } else {
    if (clues.length !== 5) {
      errors.push(`word_unlock must have exactly 5 clues. Found ${clues.length}.`);
    }

    const revealedLetters = [];

    clues.forEach((clue, index) => {
      const clueNumber = Number(clue.clue_number || index + 1);
      const answer = normalizeText(clue.answer);
      const revealedLetter = normalizeText(clue.revealed_letter);
      const position = Number(clue.revealed_letter_position_in_answer);

      if (!hasValue(clue.clue)) {
        errors.push(`Clue ${clueNumber}: missing clue.`);
      }

      if (!hasValue(clue.hint)) {
        errors.push(`Clue ${clueNumber}: missing hint.`);
      }

      if (!answer) {
        errors.push(`Clue ${clueNumber}: missing answer.`);
        return;
      }

      if (!revealedLetter) {
        errors.push(`Clue ${clueNumber}: missing revealed_letter.`);
        return;
      }

      if (revealedLetter.length !== 1) {
        errors.push(`Clue ${clueNumber}: revealed_letter must be exactly one letter.`);
        return;
      }

      if (!Number.isInteger(position) || position < 1 || position > answer.length) {
        errors.push(`Clue ${clueNumber}: invalid revealed_letter_position_in_answer.`);
        return;
      }

      const actualLetter = answer[position - 1];

      if (actualLetter !== revealedLetter) {
        errors.push(
          `Clue ${clueNumber}: position ${position} in "${answer}" is "${actualLetter}", not "${revealedLetter}".`
        );
      }

      revealedLetters.push(revealedLetter);

      clue.clue_number = clueNumber;
      clue.answer = answer;
      clue.revealed_letter = revealedLetter;
      clue.revealed_letter_position_in_answer = position;
    });

    const unlockedWord = revealedLetters.join("");
    const finalAnswer = normalizeText(puzzle.answer);

    puzzle.answer = finalAnswer;

    if (finalAnswer.length !== 5) {
      errors.push(`word_unlock answer must be 5 letters. Found ${finalAnswer.length}.`);
    }

    if (unlockedWord !== finalAnswer) {
      errors.push(
        `Revealed letters spell "${unlockedWord}", but top-level answer is "${finalAnswer}".`
      );
    }

    if (puzzle.puzzle_data.final_word_length !== finalAnswer.length) {
      errors.push(
        `final_word_length is ${puzzle.puzzle_data.final_word_length}, but answer length is ${finalAnswer.length}.`
      );
    }
  }
}

/* -----------------------------
   ODD ONE OUT VALIDATION
------------------------------ */

if (puzzle.puzzle_type === "odd_one_out") {
  const items = puzzle.puzzle_data?.items;
  const oddItemId = normalizeString(puzzle.puzzle_data?.odd_item_id).toUpperCase();
  const hiddenRule = normalizeString(puzzle.puzzle_data?.hidden_rule);
  const hint = normalizeString(puzzle.puzzle_data?.hint);

  if (!Array.isArray(items)) {
    errors.push("odd_one_out puzzle_data.items must be an array.");
  } else {
    if (items.length !== 5) {
      errors.push(`odd_one_out must have exactly 5 items. Found ${items.length}.`);
    }

    const itemIds = [];

    items.forEach((item, index) => {
      const expectedId = String.fromCharCode(65 + index);
      const id = normalizeString(item.id || expectedId).toUpperCase();
      const text = normalizeString(item.text);

      if (!id) {
        errors.push(`Item ${index + 1}: missing id.`);
      }

      if (!text) {
        errors.push(`Item ${id || index + 1}: missing text.`);
      }

      item.id = id;
      item.text = text;

      itemIds.push(id);
    });

    const uniqueIds = new Set(itemIds);

    if (uniqueIds.size !== itemIds.length) {
      errors.push("odd_one_out item ids must be unique.");
    }

    if (!oddItemId) {
      errors.push("odd_one_out missing odd_item_id.");
    } else if (!itemIds.includes(oddItemId)) {
      errors.push(`odd_item_id "${oddItemId}" does not match any item id.`);
    }

    if (!hiddenRule) {
      errors.push("odd_one_out missing hidden_rule.");
    }

    if (!hint) {
      errors.push("odd_one_out missing hint.");
    }

    const oddItem = items.find(item => item.id === oddItemId);

    if (oddItem && puzzle.answer) {
      const normalizedTopAnswer = normalizeString(puzzle.answer).toUpperCase();
      const normalizedOddText = normalizeString(oddItem.text).toUpperCase();

      if (normalizedTopAnswer !== normalizedOddText) {
        errors.push(
          `Top-level answer "${puzzle.answer}" does not match odd item text "${oddItem.text}".`
        );
      }
    }

    puzzle.puzzle_data.odd_item_id = oddItemId;
    puzzle.puzzle_data.hidden_rule = hiddenRule;
    puzzle.puzzle_data.hint = hint;

    if (oddItem) {
      puzzle.answer = oddItem.text;
    }
  }
}

/* -----------------------------
   SEQUENCE / QUICK LOGIC VALIDATION
------------------------------ */

if (puzzle.puzzle_type === "sequence_puzzle") {
  const sequence = puzzle.puzzle_data?.sequence;
  const options = puzzle.puzzle_data?.options;
  const correctOptionId = normalizeString(puzzle.puzzle_data?.correct_option_id).toUpperCase();
  const patternType = normalizeString(puzzle.puzzle_data?.pattern_type);
  const hint = normalizeString(puzzle.puzzle_data?.hint);

  const normalizedPatternType = patternType.toLowerCase();

  const singlePromptPatternTypes = [
    "order-of-operations",
    "bodmas",
    "bidmas",
    "arithmetic",
    "quick-arithmetic",
    "quick-logic",
    "missing-number",
    "missing-operator",
    "logic-puzzle",
    "math-logic",
    "calculation"
  ];

  const allowsSinglePrompt = singlePromptPatternTypes.includes(normalizedPatternType);

  if (!Array.isArray(sequence)) {
    errors.push("sequence_puzzle puzzle_data.sequence must be an array.");
  } else {
    if (sequence.length < 1) {
      errors.push("sequence_puzzle sequence must contain at least 1 item.");
    }

    if (!allowsSinglePrompt && sequence.length < 3) {
      errors.push(
        `sequence_puzzle sequence should have at least 3 items for pattern_type "${patternType}". Found ${sequence.length}.`
      );
    }

    if (allowsSinglePrompt && sequence.length !== 1) {
      errors.push(
        `sequence_puzzle with pattern_type "${patternType}" should usually contain exactly 1 puzzle expression/prompt in sequence. Found ${sequence.length}.`
      );
    }
  }

  if (!Array.isArray(options)) {
    errors.push("sequence_puzzle puzzle_data.options must be an array.");
  } else {
    if (options.length !== 4) {
      errors.push(`sequence_puzzle must have exactly 4 options. Found ${options.length}.`);
    }

    const optionIds = [];

    options.forEach((option, index) => {
      const expectedId = String.fromCharCode(65 + index);
      const id = normalizeString(option.id || expectedId).toUpperCase();
      const text = normalizeString(option.text);

      if (!id) {
        errors.push(`Option ${index + 1}: missing id.`);
      }

      if (!text) {
        errors.push(`Option ${id || index + 1}: missing text.`);
      }

      option.id = id;
      option.text = text;

      optionIds.push(id);
    });

    const uniqueOptionIds = new Set(optionIds);

    if (uniqueOptionIds.size !== optionIds.length) {
      errors.push("sequence_puzzle option ids must be unique.");
    }

    if (!correctOptionId) {
      errors.push("sequence_puzzle missing correct_option_id.");
    } else if (!optionIds.includes(correctOptionId)) {
      errors.push(`correct_option_id "${correctOptionId}" does not match any option id.`);
    }

    const correctOption = options.find(option => option.id === correctOptionId);

    if (correctOption && puzzle.answer) {
      const normalizedTopAnswer = normalizeString(puzzle.answer).toUpperCase();
      const normalizedCorrectText = normalizeString(correctOption.text).toUpperCase();

      if (normalizedTopAnswer !== normalizedCorrectText) {
        errors.push(
          `Top-level answer "${puzzle.answer}" does not match correct option text "${correctOption.text}".`
        );
      }
    }

    if (correctOption) {
      puzzle.answer = correctOption.text;
    }
  }

  if (!hasValue(puzzle.puzzle_data?.question)) {
    errors.push("sequence_puzzle missing question.");
  }

  if (!patternType) {
    errors.push("sequence_puzzle missing pattern_type.");
  }

  if (!hint) {
    errors.push("sequence_puzzle missing hint.");
  }

  puzzle.puzzle_data.correct_option_id = correctOptionId;
  puzzle.puzzle_data.pattern_type = patternType;
  puzzle.puzzle_data.hint = hint;
}

/* -----------------------------
   MINI RIDDLE VALIDATION
------------------------------ */

if (puzzle.puzzle_type === "mini_riddle") {
  const riddle = normalizeString(puzzle.puzzle_data?.riddle);
  const hint = normalizeString(puzzle.puzzle_data?.hint);
  const dataAnswer = normalizeText(puzzle.puzzle_data?.answer);
  const topAnswer = normalizeText(puzzle.answer);

  if (!riddle) {
    errors.push("mini_riddle missing riddle.");
  }

  if (!hint) {
    errors.push("mini_riddle missing hint.");
  }

  if (!dataAnswer) {
    errors.push("mini_riddle missing puzzle_data.answer.");
  }

  if (!topAnswer) {
    errors.push("mini_riddle missing top-level answer.");
  }

  if (dataAnswer && topAnswer && dataAnswer !== topAnswer) {
    errors.push(
      `mini_riddle top-level answer "${puzzle.answer}" does not match puzzle_data.answer "${puzzle.puzzle_data.answer}".`
    );
  }

  if (dataAnswer && dataAnswer.length < 2) {
    errors.push("mini_riddle answer is too short.");
  }

  if (dataAnswer && dataAnswer.length > 30) {
    errors.push("mini_riddle answer is too long.");
  }

  puzzle.puzzle_data.riddle = riddle;
  puzzle.puzzle_data.hint = hint;
  puzzle.puzzle_data.answer = dataAnswer;
  puzzle.answer = dataAnswer || topAnswer;
}

/* -----------------------------
   COMMON FIELD CHECKS
------------------------------ */

if (!hasValue(puzzle.title)) {
  errors.push("Missing title.");
}

if (!["easy", "medium", "hard"].includes(String(puzzle.difficulty || "").toLowerCase())) {
  errors.push(`Invalid difficulty: ${puzzle.difficulty}`);
}

if (
  !Number.isInteger(Number(puzzle.estimated_time_minutes)) ||
  Number(puzzle.estimated_time_minutes) < 3 ||
  Number(puzzle.estimated_time_minutes) > 7
) {
  errors.push("estimated_time_minutes must be a number between 3 and 7.");
}

if (!hasValue(puzzle.instructions)) {
  errors.push("Missing instructions.");
}

if (!hasValue(puzzle.explanation)) {
  errors.push("Missing explanation.");
}

if (!hasValue(puzzle.share_text)) {
  errors.push("Missing share_text.");
}

if (!puzzle.gameplay_rules || typeof puzzle.gameplay_rules !== "object") {
  errors.push("Missing gameplay_rules object.");
}

/* -----------------------------
   GAMEPLAY RULES VALIDATION
------------------------------ */

if (puzzle.gameplay_rules && typeof puzzle.gameplay_rules === "object") {
  const rules = puzzle.gameplay_rules;

  if (puzzle.puzzle_type === "word_unlock") {
    if (!Number.isInteger(Number(rules.clue_attempts_allowed))) {
      errors.push("word_unlock gameplay_rules missing clue_attempts_allowed.");
    }

    if (!Number.isInteger(Number(rules.show_hint_after_wrong_attempts))) {
      errors.push("word_unlock gameplay_rules missing show_hint_after_wrong_attempts.");
    }

    if (!Number.isInteger(Number(rules.reveal_answer_after_wrong_attempts))) {
      errors.push("word_unlock gameplay_rules missing reveal_answer_after_wrong_attempts.");
    }

    if (!Number.isInteger(Number(rules.final_answer_attempts_allowed))) {
      errors.push("word_unlock gameplay_rules missing final_answer_attempts_allowed.");
    }
  }

  if (
    puzzle.puzzle_type === "odd_one_out" ||
    puzzle.puzzle_type === "sequence_puzzle" ||
    puzzle.puzzle_type === "mini_riddle"
  ) {
    if (!Number.isInteger(Number(rules.attempts_allowed))) {
      errors.push(`${puzzle.puzzle_type} gameplay_rules missing attempts_allowed.`);
    }

    if (!Number.isInteger(Number(rules.show_hint_after_wrong_attempts))) {
      errors.push(`${puzzle.puzzle_type} gameplay_rules missing show_hint_after_wrong_attempts.`);
    }

    if (!Number.isInteger(Number(rules.reveal_answer_after_wrong_attempts))) {
      errors.push(`${puzzle.puzzle_type} gameplay_rules missing reveal_answer_after_wrong_attempts.`);
    }

    if ("clue_attempts_allowed" in rules) {
      errors.push(`${puzzle.puzzle_type} should use attempts_allowed, not clue_attempts_allowed.`);
    }

    if ("final_answer_attempts_allowed" in rules) {
      errors.push(`${puzzle.puzzle_type} should not use final_answer_attempts_allowed.`);
    }
  }
}

puzzle.validation = {
  is_valid: errors.length === 0,
  errors
};

return [
  {
    json: puzzle
  }
];

const previousPuzzle = $json;

const currentAttempt = Number(previousPuzzle.generation_attempt || 1);
const nextAttempt = currentAttempt + 1;
const maxAttempts = 3;

const canRegenerate = nextAttempt <= maxAttempts;

// Get failed answer safely for all puzzle types
let previousFailedAnswer = previousPuzzle.answer || null;

// Extra fallback for mini_riddle
if (previousPuzzle.puzzle_type === "mini_riddle") {
  previousFailedAnswer =
    previousPuzzle.answer ||
    previousPuzzle.puzzle_data?.answer ||
    null;
}

// Extra fallback for sequence_puzzle
if (previousPuzzle.puzzle_type === "sequence_puzzle") {
  const correctOptionId = String(previousPuzzle.puzzle_data?.correct_option_id || "").trim().toUpperCase();
  const correctOption = previousPuzzle.puzzle_data?.options?.find(
    option => String(option.id || "").trim().toUpperCase() === correctOptionId
  );

  previousFailedAnswer =
    previousPuzzle.answer ||
    correctOption?.text ||
    null;
}

// Extra fallback for odd_one_out
if (previousPuzzle.puzzle_type === "odd_one_out") {
  const oddItemId = String(previousPuzzle.puzzle_data?.odd_item_id || "").trim().toUpperCase();
  const oddItem = previousPuzzle.puzzle_data?.items?.find(
    item => String(item.id || "").trim().toUpperCase() === oddItemId
  );

  previousFailedAnswer =
    previousPuzzle.answer ||
    oddItem?.text ||
    null;
}

// Extra fallback for word_unlock
if (previousPuzzle.puzzle_type === "word_unlock") {
  previousFailedAnswer =
    previousPuzzle.answer ||
    null;
}

return [
  {
    json: {
      date: previousPuzzle.date,
      rotation_day_number: previousPuzzle.rotation_day_number,
      puzzle_type: previousPuzzle.puzzle_type,
      difficulty: previousPuzzle.difficulty || "medium",

      generation_attempt: nextAttempt,
      max_generation_attempts: maxAttempts,
      can_regenerate: canRegenerate,

      previous_failed_answer: previousFailedAnswer,
      previous_failed_title: previousPuzzle.title || null,
      previous_validation_errors: previousPuzzle.validation?.errors || [],
      previous_auto_fix: previousPuzzle.auto_fix || null,

      regeneration_reason: "Puzzle was still invalid after auto-fix and second validation."
    }
  }
];

const puzzle = $json;

function ordinal(n) {
  const num = Number(n);
  const suffixes = ["th", "st", "nd", "rd"];
  const value = num % 100;
  return num + (suffixes[(value - 20) % 10] || suffixes[value] || suffixes[0]);
}

if (puzzle.puzzle_type === "word_unlock") {
  const clues = puzzle.puzzle_data?.clues || [];

  const explanationParts = clues.map(clue => {
    return `${clue.answer} -> ${clue.revealed_letter} (${ordinal(clue.revealed_letter_position_in_answer)})`;
  });

  puzzle.explanation = `Each solved clue revealed one letter in order: ${explanationParts.join(", ")}. Those letters spell the final 5-letter word ${puzzle.answer}.`;
}

puzzle.status = puzzle.status || "draft";
puzzle.ready_for_storage = true;
puzzle.generated_at = puzzle.generated_at || new Date().toISOString();

puzzle.source = {
  generated_by: "n8n",
  validation_passed: puzzle.validation?.is_valid === true,
  auto_fixed: puzzle.auto_fix?.fixed || false,
  generation_attempt: puzzle.generation_attempt || 1
};

return [
  {
    json: puzzle
  }
];

const selectedPuzzle = $("Select Daily Puzzle Type").first().json;

// Rows returned from Supabase.
// If no rows exist yet, n8n may pass one empty item because "Always Output Data" is enabled.
const recentPuzzles = $input
  .all()
  .map(item => item.json)
  .filter(row => row && row.id);

// Collect recent final answers
const recentAnswers = recentPuzzles
  .map(p => p.answer)
  .filter(Boolean);

// Collect recent titles
const recentTitles = recentPuzzles
  .map(p => p.title)
  .filter(Boolean);

// Collect recent clue/item/option answers
const recentClueAnswers = [];

recentPuzzles.forEach(puzzle => {
  if (puzzle.puzzle_type === "word_unlock") {
    const clues = puzzle.puzzle_data?.clues || [];

    clues.forEach(clue => {
      if (clue.answer) {
        recentClueAnswers.push(clue.answer);
      }
    });
  }

  if (puzzle.puzzle_type === "odd_one_out") {
    const items = puzzle.puzzle_data?.items || [];

    items.forEach(item => {
      if (item.text) {
        recentClueAnswers.push(item.text);
      }
    });
  }

  if (puzzle.puzzle_type === "sequence_puzzle") {
    const options = puzzle.puzzle_data?.options || [];

    options.forEach(option => {
      if (option.text) {
        recentClueAnswers.push(option.text);
      }
    });
  }
});

// Short history summary
const recentPuzzleSummary = recentPuzzles.map(p => ({
  date: p.date,
  puzzle_type: p.puzzle_type,
  title: p.title,
  answer: p.answer,
  status: p.status
}));

return [
  {
    json: {
      ...selectedPuzzle,

      recent_answers: recentAnswers,
      recent_titles: recentTitles,
      recent_clue_answers: recentClueAnswers,
      recent_puzzle_summary: recentPuzzleSummary
    }
  }
];
